+		(nested_vmcb->control.int_ctl & int_ctl_vmcb12_bits) |
+		(hsave->control.int_ctl & int_ctl_vmcb01_bits);
 	if (nested_vmcb->control.int_ctl & V_INTR_MASKING_MASK)
